    b.append('<div class="callout c-new"><b>🆕 v2.1.0（2026-11-14）更新</b><p>'+md("**三级可折叠目录**（一级编号、每级可展开/折叠、拖动目录边缘自由调宽）· 每页顶部 **⚡ 30 秒抓核心** · 每卷 **地理节奏条**（一章一格看懂全书地理）· 新增 **节期轮**、**步行距离图**、**权力金字塔** · 实时地图 **17 个实测底图** + 并行测速自动选源 · 装饰动画屏幕外/滚动中自动暂停，滚动更顺。")+'</p><p><a class="btn" href="maps.html">🌍 打开地图页</a></p></div>'+orbit(eps))
